-- Phase 141: TENANT_CONFIG_* permission catalog'iga qo'shish va default
-- system role'larga (ADMIN, ENGINEER, TESTER, VIEWER) least-privilege
-- role_permission bog'lanishlarini seed qilish.
--
-- Phase 139'dan keyingi enforcement gap'ni yopadi:
--   AdminAuthorizationService TENANT_CONFIG_READ/WRITE'ni enforce qiladi —
--     bu ikkita kod V2'da catalog row sifatida mavjud emas edi, shu yerda
--     qo'shiladi.
--   OperationalAuthorizationService WORK_ITEM_CREATE/TRANSITION'ni enforce
--     qiladi — ikkalasi V2 catalog'da mavjud, lekin hech qaysi rolga
--     biriktirilmagan, shu yerda biriktiriladi.
--
-- Bu migration faqat permission catalog + role_permission grantlarini hal
-- qiladi. Tenant/app_user/membership/membership_role_binding bootstrap'i
-- alohida masala (Phase 142) — shu sababli real production deployment'da
-- hali ham operator dastlabki admin actor'ni qo'lda yaratishi shart bo'ladi.

-- =====================================================================
-- SEED DATA: TENANT_CONFIG_* permission'lari
-- =====================================================================

INSERT INTO permission (id, code, description) VALUES
    ('a0000000-0000-0000-0000-00000000000c', 'TENANT_CONFIG_READ', 'Tenant konfiguratsiyasini ko''rish'),
    ('a0000000-0000-0000-0000-00000000000d', 'TENANT_CONFIG_WRITE', 'Tenant konfiguratsiyasini boshqarish');

